<?php declare(strict_types=1); namespace Annam; $title=$item['name'].' · '.$store->name(); ?>
<section class="wrap php-store-section"><a href="<?= $item['fulfilment']==='courier'?'/shop/':'/menu/' ?>">← Back to <?= $item['fulfilment']==='courier'?'shop':'menu' ?></a><div class="php-item-grid"><?php if ($item['image']): ?><img class="php-item-image" src="<?= e(image_url($item['image'])) ?>" alt="<?= e($item['name']) ?>"><?php endif; ?><div><h1><?= e($item['name']) ?></h1><p class="price"><?= money($item['price']) ?></p><p><?= nl2br(e($item['description'])) ?></p><?php if ($item['fulfilment']==='courier'): ?><form method="post" action="/cart/add/"><?= csrf() ?><input type="hidden" name="item_id" value="<?= e($item['id']) ?>"><label>Quantity <input type="number" name="quantity" value="1" min="1" max="99" required></label><button class="btn btn-primary" type="submit">Add to cart →</button></form><?php else: ?><a class="btn btn-primary" href="/menu/">Choose date and meal →</a><?php endif; ?></div></div></section>
